begin;
create extension if not exists supabase_vault with schema vault;
create or replace function public.store_whatsapp_access_token(target_secret_name text,target_access_token text) returns void language plpgsql security definer set search_path=public,vault as $$ declare existing_id uuid; begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'forbidden'; end if; if nullif(trim(target_secret_name),'') is null or nullif(trim(target_access_token),'') is null then raise exception 'invalid_secret'; end if; select id into existing_id from vault.secrets where name=target_secret_name limit 1; if existing_id is null then perform vault.create_secret(target_access_token,target_secret_name,'WhatsApp Cloud API — cadastro incorporado'); else perform vault.update_secret(existing_id,target_access_token,target_secret_name,'WhatsApp Cloud API — cadastro incorporado'); end if; end; $$;
revoke all on function public.store_whatsapp_access_token(text,text) from public,anon,authenticated; grant execute on function public.store_whatsapp_access_token(text,text) to service_role;
create or replace function public.get_whatsapp_access_token(target_secret_name text) returns text language plpgsql security definer set search_path=public,vault as $$ declare result text; begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'forbidden'; end if; select decrypted_secret into result from vault.decrypted_secrets where name=target_secret_name limit 1; return result; end; $$;
revoke all on function public.get_whatsapp_access_token(text) from public,anon,authenticated; grant execute on function public.get_whatsapp_access_token(text) to service_role;
commit;
